import pandas as pd
import requests
from datetime import datetime, timezone, timedelta

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())
from_date = (now - timedelta(days=30)).strftime('%Y-%m-%d')
to_date = now.strftime('%Y-%m-%d')

BASE = 'https://api.reporter.nih.gov/v2/projects/search'

EXPECTED_COLUMNS = [
    'project_num', 'project_title',
    'organization_name', 'organization_state',
    'agency_ic_admin', 'agency_ic_funding',
    'award_amount', 'total_cost', 'fiscal_year',
    'project_start_date', 'project_end_date',
    'pi_name', 'spending_category',
    'project_url', '_epoch',
]

rows = []
offset = 0
page_size = 100
max_pages = 3
fy_current = now.year
for page_idx in range(max_pages):
    body = {
        'criteria': {
            'fiscal_years': [fy_current, fy_current - 1],
            'project_start_date': {
                'from_date': from_date,
                'to_date': to_date,
            },
            'include_active_projects': True,
        },
        'limit': page_size,
        'offset': offset,
        'sort_field': 'award_amount',
        'sort_order': 'desc',
    }
    try:
        resp = requests.post(
            BASE,
            json=body,
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        results = payload.get('results', []) or []
    except Exception:
        break
    if not results:
        break
    for ri in range(len(results)):
        r = results[ri]
        if not isinstance(r, dict):
            continue
        proj_num = r.get('project_num', '') or r.get('appl_id', '') or ''
        title = r.get('project_title', '') or ''
        org_obj = r.get('organization', {}) or {}
        org_name = ''
        org_state = ''
        if isinstance(org_obj, dict):
            org_name = org_obj.get('org_name', '') or org_obj.get('name', '') or ''
            org_state = org_obj.get('org_state', '') or org_obj.get('state', '') or ''
        agency_ic_admin = r.get('agency_ic_admin', {}) or {}
        agency_admin_code = ''
        if isinstance(agency_ic_admin, dict):
            agency_admin_code = agency_ic_admin.get('code', '') or ''
        agency_ic_funding = r.get('agency_ic_fundings', []) or []
        funding_codes = []
        if isinstance(agency_ic_funding, list):
            for fi in range(len(agency_ic_funding)):
                f = agency_ic_funding[fi]
                if isinstance(f, dict):
                    code = f.get('code', '') or ''
                    if code:
                        funding_codes.append(code)
        funding_str = '; '.join(funding_codes[:3])
        award = r.get('award_amount', 0) or 0
        try:
            award_amount = float(award)
        except Exception:
            award_amount = 0.0
        total_cost = r.get('award_notice_date', None)
        try:
            total_cost_val = float(r.get('total_cost', 0) or 0)
        except Exception:
            total_cost_val = 0.0
        fy = r.get('fiscal_year', 0) or 0
        try:
            fy_int = int(fy)
        except Exception:
            fy_int = 0
        start_date = r.get('project_start_date', '') or ''
        end_date = r.get('project_end_date', '') or ''
        contact_pi = r.get('contact_pi_name', '') or ''
        if not contact_pi:
            pis = r.get('principal_investigators', []) or []
            if isinstance(pis, list) and len(pis) > 0 and isinstance(pis[0], dict):
                contact_pi = pis[0].get('full_name', '') or ''
        spending_obj = r.get('spending_categories', []) or []
        spending_str = ''
        if isinstance(spending_obj, list) and spending_obj:
            spend_names = []
            for si in range(len(spending_obj)):
                spc = spending_obj[si]
                if isinstance(spc, dict):
                    nm = spc.get('name', '') or ''
                    if nm:
                        spend_names.append(nm)
                elif isinstance(spc, str):
                    spend_names.append(spc)
            spending_str = '; '.join(spend_names[:3])
        proj_url = ''
        if proj_num:
            proj_url = 'https://reporter.nih.gov/project-details/' + str(proj_num)
        rows.append({
            'project_num': str(proj_num),
            'project_title': title[:300] if len(title) > 300 else title,
            'organization_name': org_name,
            'organization_state': org_state,
            'agency_ic_admin': agency_admin_code,
            'agency_ic_funding': funding_str,
            'award_amount': round(award_amount, 2),
            'total_cost': round(total_cost_val, 2),
            'fiscal_year': fy_int,
            'project_start_date': start_date,
            'project_end_date': end_date,
            'pi_name': contact_pi,
            'spending_category': spending_str,
            'project_url': proj_url,
            '_epoch': now_epoch,
        })
    if len(results) < page_size:
        break
    offset = offset + page_size

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
    df = df.sort_values('award_amount', ascending=False).reset_index(drop=True)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
